template:
struct Config { port: u16 }
struct Builder { port: u16 }

impl Builder {
    fn new() -> Self { Builder { port: 80 } }
    fn port(⟦slot1⟧, port: u16) -> ⟦slot2⟧ {
        self.port = port;
        self
    }
    fn build(self) -> Config { Config { port: self.port } }
}

fn main() {
    let c = Builder::new().port(8080).build();
    assert_eq!(c.port, 8080);
}

tests:
#[test]
fn test_builder_port() {
    let c = Builder::new().port(9000).build();
    assert_eq!(c.port, 9000);
}
